pub struct Counter {
    value: i32,
}

impl Counter {
    pub fn new() -> Self { Counter { value: 0 } }
    pub fn value(&self) -> i32 { self.value }
    pub fn increment(&mut self) { self.value += 1; }
    pub fn reset(&mut self) { self.value = 0; }
}

fn main() {
    let mut c = Counter::new();
    c.increment();
    println!("{}", c.value());
}
